<?php
require_once __DIR__.'/../auth/check.php';requireRole('BacSi');require_once __DIR__.'/../config/database.php';
$s=$pdo->prepare('SELECT MaBS,HoTen FROM BacSi WHERE MaTK=?');$s->execute([$_SESSION['user']['MaTK']]);$bs=$s->fetch();if(!$bs)exit('Không tìm thấy bác sĩ.');$madl=(int)($_GET['appointment']??$_POST['MaDatLich']??0);if(!$madl)exit('Thiếu mã lịch hẹn.');
$s=$pdo->prepare('SELECT dl.*,bn.HoTen TenBN,bn.GioiTinh,bn.NgaySinh,bn.SoDienThoai,bn.Email,bn.DiaChi,lk.NgayKham,lk.GioBatDau,lk.GioKetThuc FROM DatLich dl JOIN BenhNhan bn ON dl.MaBN=bn.MaBN JOIN LichKham lk ON dl.MaLich=lk.MaLich WHERE dl.MaDatLich=? AND lk.MaBS=?');$s->execute([$madl,$bs['MaBS']]);$a=$s->fetch();if(!$a){http_response_code(403);exit('Lịch hẹn không thuộc bác sĩ này.');}
$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 try{
  if($action==='save_record'){$cd=trim($_POST['ChanDoan']??'');$kl=trim($_POST['KetLuan']??'');$hd=trim($_POST['HuongDieuTri']??'');$gc=trim($_POST['GhiChu']??'');$pdo->beginTransaction();$s=$pdo->prepare('SELECT MaHS FROM HoSoKham WHERE MaDatLich=?');$s->execute([$madl]);$mahs=$s->fetchColumn();if($mahs){$pdo->prepare('UPDATE HoSoKham SET ChanDoan=?,KetLuan=?,HuongDieuTri=?,GhiChu=?,ThoiGianKham=NOW() WHERE MaHS=?')->execute([$cd?:null,$kl?:null,$hd?:null,$gc?:null,$mahs]);}else{$pdo->prepare('INSERT INTO HoSoKham(MaDatLich,ChanDoan,KetLuan,HuongDieuTri,GhiChu) VALUES(?,?,?,?,?)')->execute([$madl,$cd?:null,$kl?:null,$hd?:null,$gc?:null]);$mahs=(int)$pdo->lastInsertId();}$pdo->prepare("UPDATE DatLich SET TrangThai='DaKham' WHERE MaDatLich=?")->execute([$madl]);$pdo->commit();$ok='Đã lưu hồ sơ khám.';}
  elseif($action==='save_prescription'){$loidan=trim($_POST['LoiDan']??'');$s=$pdo->prepare('SELECT MaHS FROM HoSoKham WHERE MaDatLich=?');$s->execute([$madl]);$mahs=(int)$s->fetchColumn();if(!$mahs)throw new Exception('Hãy lưu hồ sơ khám trước khi kê đơn.');$s=$pdo->prepare('SELECT MaDon FROM DonThuoc WHERE MaHS=?');$s->execute([$mahs]);$madon=$s->fetchColumn();if($madon)$pdo->prepare('UPDATE DonThuoc SET LoiDan=?,NgayKeDon=NOW() WHERE MaDon=?')->execute([$loidan?:null,$madon]);else{$pdo->prepare('INSERT INTO DonThuoc(MaHS,LoiDan) VALUES(?,?)')->execute([$mahs,$loidan?:null]);}$ok='Đã lưu lời dặn đơn thuốc.';}
  elseif($action==='add_medicine'){$s=$pdo->prepare('SELECT MaHS FROM HoSoKham WHERE MaDatLich=?');$s->execute([$madl]);$mahs=(int)$s->fetchColumn();if(!$mahs)throw new Exception('Hãy lưu hồ sơ khám trước.');$s=$pdo->prepare('SELECT MaDon FROM DonThuoc WHERE MaHS=?');$s->execute([$mahs]);$madon=(int)$s->fetchColumn();if(!$madon){$pdo->prepare('INSERT INTO DonThuoc(MaHS) VALUES(?)')->execute([$mahs]);$madon=(int)$pdo->lastInsertId();}$mathuoc=(int)($_POST['MaThuoc']??0);$sl=max(1,(int)($_POST['SoLuong']??1));$lieu=trim($_POST['LieuDung']??'');$cach=trim($_POST['CachDung']??'');$pdo->beginTransaction();$s=$pdo->prepare('SELECT SoLuongTon,TrangThai FROM Thuoc WHERE MaThuoc=? FOR UPDATE');$s->execute([$mathuoc]);$t=$s->fetch();if(!$t||!$t['TrangThai'])throw new Exception('Thuốc không khả dụng.');if($t['SoLuongTon']<$sl)throw new Exception('Không đủ thuốc trong kho.');$pdo->prepare('INSERT INTO ChiTietDonThuoc(MaDon,MaThuoc,SoLuong,LieuDung,CachDung) VALUES(?,?,?,?,?)')->execute([$madon,$mathuoc,$sl,$lieu?:null,$cach?:null]);$pdo->prepare('UPDATE Thuoc SET SoLuongTon=SoLuongTon-? WHERE MaThuoc=?')->execute([$sl,$mathuoc]);$pdo->commit();$ok='Đã thêm thuốc vào đơn.';}
  elseif($action==='remove_medicine'){$mact=(int)($_POST['MaCT']??0);$pdo->beginTransaction();$s=$pdo->prepare('SELECT ct.MaThuoc,ct.SoLuong FROM ChiTietDonThuoc ct JOIN DonThuoc d ON ct.MaDon=d.MaDon JOIN HoSoKham hs ON d.MaHS=hs.MaHS WHERE ct.MaCT=? AND hs.MaDatLich=? FOR UPDATE');$s->execute([$mact,$madl]);$ct=$s->fetch();if($ct){$pdo->prepare('DELETE FROM ChiTietDonThuoc WHERE MaCT=?')->execute([$mact]);$pdo->prepare('UPDATE Thuoc SET SoLuongTon=SoLuongTon+? WHERE MaThuoc=?')->execute([$ct['SoLuong'],$ct['MaThuoc']]);}$pdo->commit();$ok='Đã xóa thuốc khỏi đơn.';}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$s=$pdo->prepare('SELECT * FROM HoSoKham WHERE MaDatLich=?');$s->execute([$madl]);$hs=$s->fetch();$don=null;$details=[];if($hs){$s=$pdo->prepare('SELECT * FROM DonThuoc WHERE MaHS=?');$s->execute([$hs['MaHS']]);$don=$s->fetch();if($don){$s=$pdo->prepare('SELECT ct.*,t.TenThuoc,t.DonVi FROM ChiTietDonThuoc ct JOIN Thuoc t ON ct.MaThuoc=t.MaThuoc WHERE ct.MaDon=? ORDER BY ct.MaCT');$s->execute([$don['MaDon']]);$details=$s->fetchAll();}}$thuoc=$pdo->query('SELECT MaThuoc,TenThuoc,DonVi,SoLuongTon FROM Thuoc WHERE TrangThai=1 AND SoLuongTon>0 ORDER BY TenThuoc')->fetchAll();
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hồ sơ khám</title><link href="../assets/vendor/bootstrap/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between"><h2>Hồ sơ khám bệnh</h2><a class="btn btn-outline-secondary" href="appointments.php">Lịch khám</a></div><div class="card card-body my-3"><strong><?=htmlspecialchars($a['TenBN'])?></strong><span>SĐT: <?=htmlspecialchars($a['SoDienThoai'])?> | Ngày khám: <?=$a['NgayKham']?> <?=substr($a['GioBatDau'],0,5)?></span><span>Lý do: <?=htmlspecialchars($a['LyDoKham']??'')?></span><span>Triệu chứng: <?=htmlspecialchars($a['TrieuChung']??'')?></span></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($ok):?><div class="alert alert-success"><?=htmlspecialchars($ok)?></div><?php endif;?>
<form method="post" class="card card-body mb-4"><input type="hidden" name="action" value="save_record"><input type="hidden" name="MaDatLich" value="<?=$madl?>"><h5>Kết quả khám</h5><div class="row g-2"><div class="col-md-6"><textarea name="ChanDoan" class="form-control" placeholder="Chẩn đoán"><?=htmlspecialchars($hs['ChanDoan']??'')?></textarea></div><div class="col-md-6"><textarea name="KetLuan" class="form-control" placeholder="Kết luận"><?=htmlspecialchars($hs['KetLuan']??'')?></textarea></div><div class="col-md-6"><textarea name="HuongDieuTri" class="form-control" placeholder="Hướng điều trị"><?=htmlspecialchars($hs['HuongDieuTri']??'')?></textarea></div><div class="col-md-6"><textarea name="GhiChu" class="form-control" placeholder="Ghi chú"><?=htmlspecialchars($hs['GhiChu']??'')?></textarea></div><div class="col-12"><button class="btn btn-primary">Lưu hồ sơ & đánh dấu đã khám</button></div></div></form>
<?php if($hs):?><form method="post" class="card card-body mb-3"><input type="hidden" name="action" value="save_prescription"><input type="hidden" name="MaDatLich" value="<?=$madl?>"><h5>Đơn thuốc</h5><div class="d-flex gap-2"><input name="LoiDan" class="form-control" placeholder="Lời dặn" value="<?=htmlspecialchars($don['LoiDan']??'')?>"><button class="btn btn-secondary">Lưu lời dặn</button></div></form>
<form method="post" class="card card-body mb-3"><input type="hidden" name="action" value="add_medicine"><input type="hidden" name="MaDatLich" value="<?=$madl?>"><div class="row g-2"><div class="col-md-4"><select name="MaThuoc" class="form-select" required><option value="">Chọn thuốc</option><?php foreach($thuoc as $t):?><option value="<?=$t['MaThuoc']?>"><?=htmlspecialchars($t['TenThuoc'])?> (còn <?=$t['SoLuongTon']?> <?=htmlspecialchars($t['DonVi']??'')?>)</option><?php endforeach;?></select></div><div class="col-md-2"><input type="number" min="1" name="SoLuong" class="form-control" placeholder="Số lượng" required></div><div class="col-md-2"><input name="LieuDung" class="form-control" placeholder="Liều dùng"></div><div class="col-md-3"><input name="CachDung" class="form-control" placeholder="Cách dùng"></div><div class="col-md-1"><button class="btn btn-success w-100">Thêm</button></div></div></form>
<table class="table table-bordered"><thead><tr><th>Thuốc</th><th>Số lượng</th><th>Liều dùng</th><th>Cách dùng</th><th></th></tr></thead><tbody><?php foreach($details as $d):?><tr><td><?=htmlspecialchars($d['TenThuoc'])?></td><td><?=$d['SoLuong']?> <?=htmlspecialchars($d['DonVi']??'')?></td><td><?=htmlspecialchars($d['LieuDung']??'')?></td><td><?=htmlspecialchars($d['CachDung']??'')?></td><td><form method="post"><input type="hidden" name="action" value="remove_medicine"><input type="hidden" name="MaDatLich" value="<?=$madl?>"><input type="hidden" name="MaCT" value="<?=$d['MaCT']?>"><button class="btn btn-sm btn-outline-danger">Xóa</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?>
</div></body></html>
